# Step 4: Extract the location from the provided snippet without relying on llm_query
import re
location = None
if 'snippet' in locals() and isinstance(snippet, str):
    m = re.search(r"Stevens Institute of Technology is located in\s+([A-Za-z\s]+)\.", snippet)
    if m:
        location = m.group(1).strip()
    else:
        m2 = re.search(r"located in\s+([A-Za-z\s]+)[\.\,]", snippet)
        if m2:
            location = m2.group(1).strip()
print("Location extracted from excerpt:", location or "UNKNOWN")

final_location = location
